void far EndMigrate(int x, int y)
{
    int half;
    int from;
    unsigned char far *p;
    int tx;
    int ty;

    from = MigrateX;
    if (from < 0)
        return;
    ty = (y - 66) / 10;
    tx = (y + x - 238) / 28;
    if (tx < 0 || ty < 0 || tx > 11 || ty > 15)
        return;
    half = Dx8[from * 16 + MigrateY + 0xa4] >> 1;
    Dx8[from * 16 + MigrateY + 0xa4] -= half;
    p = &Dx8[tx * 16 + ty + 0xa4];
    if (*p + half < 0xfb)
        *p += half;
    else
        *p = 0xfa;
}
